import React from 'react';
import { CalendarEvent } from '../types';

interface RenderMonitorProps {
  events: CalendarEvent[];
  renderCounts: Record<string, number>;
}

export const RenderMonitor: React.FC<RenderMonitorProps> = ({
  events,
  renderCounts
}) => {
  const totalRenders = Object.values(renderCounts).reduce((acc, c) => acc + c, 0);
  const renderedCount = Object.values(renderCounts).filter((c) => c > 0).length;
  const maxRender = Math.max(...Object.values(renderCounts), 1);

  return (
    <div className="monitor-panel">
      <h3 className="panel-title" style={{ marginBottom: '14px' }}>
        Render Monitor
      </h3>

      <div className="monitor-stats">
        <div>
          <div className="stat-number blue">{totalRenders}</div>
          <span className="stat-desc">total renders logged</span>
        </div>
        <div>
          <div className="stat-number white">
            {renderedCount}/{events.length}
          </div>
          <span className="stat-desc">cards that have rendered</span>
        </div>
      </div>

      <div className="monitor-bars">
        {events.map((event) => {
          const count = renderCounts[event.id] || 0;
          const percentage = Math.min((count / maxRender) * 100, 100);

          return (
            <div key={event.id} className="monitor-row">
              <span className="monitor-label">{event.title}</span>
              <div className="monitor-track">
                <div
                  className="monitor-fill"
                  style={{ width: `${percentage}%` }}
                />
              </div>
              <span className="monitor-count">{count}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
};
